#!/usr/bin/env node
/**
 * Writes js/hub-seo-data.js from Hubert FAQ/schema builders (run after editing hubert-faq.js).
 */
const fs = require('fs');
const path = require('path');
const { FAQ_AEO_ENTRIES, buildSchemaGraph } = require('../api/_lib/hubert-seo');
const { STATIC_PAGES } = require('../api/_lib/seo-static-pages');

const pages = ['home', 'faq', 'contact', 'about', 'advertising', 'events', 'opportunities', 'legal'];
const schemas = {};
pages.forEach(function (page) {
  schemas[page] = buildSchemaGraph(page);
});

const dataOut =
  '/** Auto-generated by scripts/build-hub-seo-data.js — do not edit by hand */\n' +
  'window.HUB_SEO_DATA = ' +
  JSON.stringify({ faq: FAQ_AEO_ENTRIES, schemas: schemas }, null, 2) +
  ';\n';

const staticOut =
  '/** Auto-generated by scripts/build-hub-seo-data.js — do not edit by hand */\n' +
  'window.HUB_SEO_STATIC = ' +
  JSON.stringify(STATIC_PAGES, null, 2) +
  ';\n';

const dataTarget = path.join(__dirname, '..', 'js', 'hub-seo-data.js');
const staticTarget = path.join(__dirname, '..', 'js', 'hub-seo-static-config.js');
fs.writeFileSync(dataTarget, dataOut, 'utf8');
fs.writeFileSync(staticTarget, staticOut, 'utf8');
console.log('Wrote', dataTarget);
console.log('Wrote', staticTarget);
